function quickSort(nums, lo = 0, hi = nums.length - 1) {
  if (lo >= hi) return nums;                      // 0 or 1 values: nothing to do
  const p = partition(nums, lo, hi);
  quickSort(nums, lo, p - 1);                     // sort the smaller values...
  quickSort(nums, p + 1, hi);                     // ...and the bigger ones
  return nums;
}

function partition(nums, lo, hi) {
  const pivot = nums[hi];                         // Lomuto: the last value is the pivot
  let i = lo;                                     // nums[lo..i) are smaller than the pivot
  for (let j = lo; j < hi; j++) {
    if (nums[j] < pivot) {
      [nums[i], nums[j]] = [nums[j], nums[i]];
      i++;
    }
  }
  [nums[i], nums[hi]] = [nums[hi], nums[i]];      // the pivot lands in its final place
  return i;
}

def quick_sort(nums, lo=0, hi=None):
    if hi is None:
        hi = len(nums) - 1
    if lo >= hi:
        return nums                       # 0 or 1 values: nothing to do
    p = partition(nums, lo, hi)
    quick_sort(nums, lo, p - 1)           # sort the smaller values...
    quick_sort(nums, p + 1, hi)           # ...and the bigger ones
    return nums


def partition(nums, lo, hi):
    pivot = nums[hi]                      # Lomuto: the last value is the pivot
    i = lo                                # nums[lo:i] are smaller than the pivot
    for j in range(lo, hi):
        if nums[j] < pivot:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
    nums[i], nums[hi] = nums[hi], nums[i] # the pivot lands in its final place
    return i

int[] quickSort(int[] nums) {
    quickSort(nums, 0, nums.length - 1);
    return nums;
}

void quickSort(int[] nums, int lo, int hi) {
    if (lo >= hi) return;                         // 0 or 1 values: nothing to do
    int p = partition(nums, lo, hi);
    quickSort(nums, lo, p - 1);                   // sort the smaller values...
    quickSort(nums, p + 1, hi);                   // ...and the bigger ones
}

int partition(int[] nums, int lo, int hi) {
    int pivot = nums[hi];                         // Lomuto: the last value is the pivot
    int i = lo;                                   // nums[lo..i) are smaller than the pivot
    for (int j = lo; j < hi; j++) {
        if (nums[j] < pivot) {
            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;
            i++;
        }
    }
    int t = nums[i]; nums[i] = nums[hi]; nums[hi] = t;   // the pivot lands in its final place
    return i;
}

int partition(vector<int>& nums, int lo, int hi) {
    int pivot = nums[hi];                         // Lomuto: the last value is the pivot
    int i = lo;                                   // nums[lo..i) are smaller than the pivot
    for (int j = lo; j < hi; j++) {
        if (nums[j] < pivot) swap(nums[i++], nums[j]);
    }
    swap(nums[i], nums[hi]);                      // the pivot lands in its final place
    return i;
}

void quickSort(vector<int>& nums, int lo, int hi) {
    if (lo >= hi) return;                         // 0 or 1 values: nothing to do
    int p = partition(nums, lo, hi);
    quickSort(nums, lo, p - 1);                   // sort the smaller values...
    quickSort(nums, p + 1, hi);                   // ...and the bigger ones
}

vector<int> quickSort(vector<int> nums) {
    quickSort(nums, 0, (int)nums.size() - 1);
    return nums;
}
